ALTER TABLE public.tournaments ADD COLUMN game_settings jsonb;
CREATE FUNCTION public.match_winning_legs(_tournament uuid, _stage text, _round integer) RETURNS integer LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce((t.game_settings->'rounds'->(CASE WHEN _stage='small_final' THEN 'small_final' ELSE _stage || ':' || greatest(0,coalesce((SELECT max(round) FROM public.tournament_matches WHERE tournament_id=t.id AND stage=_stage),_round)-_round)::text END)->>'legsToWin')::integer,(t.game_settings->'phases'->(CASE WHEN _stage='small_final' THEN 'bracket' ELSE _stage END)->>'legsToWin')::integer,CASE WHEN _stage='pool' THEN 1 ELSE 2 END) FROM public.tournaments t WHERE t.id=_tournament $$;
REVOKE ALL ON FUNCTION public.match_winning_legs(uuid,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.match_winning_legs(uuid,text,integer) TO authenticated,service_role;
ALTER TABLE public.tournament_matches DROP CONSTRAINT tournament_matches_legs_a_check, DROP CONSTRAINT tournament_matches_legs_b_check, DROP CONSTRAINT tournament_matches_live_legs_a_check, DROP CONSTRAINT tournament_matches_live_legs_b_check;
ALTER TABLE public.tournament_matches ADD CONSTRAINT tournament_matches_legs_a_check CHECK(legs_a BETWEEN 0 AND 20), ADD CONSTRAINT tournament_matches_legs_b_check CHECK(legs_b BETWEEN 0 AND 20), ADD CONSTRAINT tournament_matches_live_legs_a_check CHECK(live_legs_a BETWEEN 0 AND 20), ADD CONSTRAINT tournament_matches_live_legs_b_check CHECK(live_legs_b BETWEEN 0 AND 20);
DO $$ DECLARE definition text; old_rule text := 'IF m.stage<>''pool'' AND NOT ((_legs_a=2 AND _legs_b IN (0,1) AND _score_a<_score_b) OR (_legs_b=2 AND _legs_a IN (0,1) AND _score_b<_score_a)) THEN RAISE EXCEPTION ''Two winning legs required''; END IF;'; new_rule text := 'IF (m.stage<>''pool'' OR public.match_winning_legs(t.id,m.stage,m.round)>1) AND NOT coalesce(((_legs_a=public.match_winning_legs(t.id,m.stage,m.round) AND _legs_b BETWEEN 0 AND public.match_winning_legs(t.id,m.stage,m.round)-1 AND _score_a<_score_b) OR (_legs_b=public.match_winning_legs(t.id,m.stage,m.round) AND _legs_a BETWEEN 0 AND public.match_winning_legs(t.id,m.stage,m.round)-1 AND _score_b<_score_a)),false) THEN RAISE EXCEPTION ''Winning legs required by match rules''; END IF;'; BEGIN definition:=pg_get_functiondef('public.commit_tournament_result(uuid,uuid,text,integer,integer,integer,integer,jsonb,jsonb)'::regprocedure); IF position(old_rule IN definition)=0 THEN RAISE EXCEPTION 'Existing result validation not recognized'; END IF; EXECUTE replace(definition,old_rule,new_rule); END $$;
CREATE FUNCTION public.lock_started_game_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status IN ('started','finished') AND (NEW.game_settings IS DISTINCT FROM OLD.game_settings OR NEW.start_score IS DISTINCT FROM OLD.start_score OR NEW.double_out IS DISTINCT FROM OLD.double_out OR NEW.final_start_score IS DISTINCT FROM OLD.final_start_score OR NEW.final_double_out IS DISTINCT FROM OLD.final_double_out OR NEW.consolation_start_score IS DISTINCT FROM OLD.consolation_start_score OR NEW.consolation_double_out IS DISTINCT FROM OLD.consolation_double_out OR NEW.pool_double_limit IS DISTINCT FROM OLD.pool_double_limit OR NEW.consolation_double_limit IS DISTINCT FROM OLD.consolation_double_limit) THEN RAISE EXCEPTION 'Les règles ne peuvent plus être modifiées après le lancement.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lock_started_game_settings BEFORE UPDATE ON public.tournaments FOR EACH ROW EXECUTE FUNCTION public.lock_started_game_settings();